sp_widget.client_script:
api.controller = function($scope) {
  var c = this;

  // Defaults
  c.data.adults = 1;
  c.data.children = 0;
  c.showModal = false;
  c.bookingConfirmed = false;
  c.isSubmitting = false;

  // If user is logged in, default guest info
  if (c.data.isLoggedIn) {
    c.data.guestName = c.data.userName;
    c.data.guestEmail = c.data.userEmail;
  }

  // Triggered when room or dates change
  c.onFormChange = function() {
    c.data.dateError = '';
    c.data.availReason = '';

    if (c.data.selectedRoom && c.data.checkIn && c.data.checkOut) {
      c.data.action = 'calculateEstimate';
      c.server.update().then(function() {
        // Updated state from server
      });
    } else {
      c.data.estimatedTotal = 0;
      c.data.nights = 0;
    }
  };

  c.onGuestCountChange = function() {
    // Check capacity if room is selected
    if (c.data.selectedRoom) {
      var room = c.getRoomObject(c.data.selectedRoom);
      if (room && (parseInt(c.data.adults, 10) + parseInt(c.data.children || 0, 10)) > parseInt(room.capacity, 10)) {
        c.data.dateError = "Total guests exceed the maximum room capacity (" + room.capacity + ").";
      } else {
        c.data.dateError = '';
      }
    }
  };

  c.canReview = function() {
    return c.data.selectedRoom && 
           c.data.checkIn && 
           c.data.checkOut && 
           c.data.guestName && 
           c.data.guestEmail && 
           c.data.isAvailable && 
           !c.data.dateError;
  };

  c.openConfirmModal = function() {
    if (c.canReview()) {
      c.showModal = true;
      c.bookingConfirmed = false;
    }
  };

  c.closeModal = function() {
    c.showModal = false;
  };

  c.confirmBooking = function() {
    c.isSubmitting = true;
    c.data.action = 'createBooking';
    c.server.update().then(function() {
      c.isSubmitting = false;
      if (c.data.bookingSuccess) {
        c.bookingConfirmed = true;
      }
    });
  };

  c.resetForm = function() {
    c.showModal = false;
    c.bookingConfirmed = false;
    c.data.selectedRoom = '';
    c.data.checkIn = '';
    c.data.checkOut = '';
    c.data.estimatedTotal = 0;
    c.data.nights = 0;
    c.data.dateError = '';
    c.data.availReason = '';
  };

  // Helper getters
  c.getRoomObject = function(roomId) {
    if (!c.data.rooms) return null;
    for (var i = 0; i < c.data.rooms.length; i++) {
      if (c.data.rooms[i].sys_id === roomId) return c.data.rooms[i];
    }
    return null;
  };

  c.getSelectedRoomName = function() {
    var r = c.getRoomObject(c.data.selectedRoom);
    return r ? r.name : '';
  };

  c.getSelectedRoomRate = function() {
    var r = c.getRoomObject(c.data.selectedRoom);
    return r ? r.rate : 0;
  };
};

sp_widget.css:
@import url('https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;600;700&family=Inter:wght@400;500;600&display=swap');

.hotel-booking-widget {
  --green: #1f3a30;
  --green-dark: #162a22;
  --green-soft: #e8eee9;
  --sand: #e6c79c;
  --sand-dark: #d4b07c;
  --cream: #faf6ef;
  --white: #ffffff;
  --text: #2a2d29;
  --muted: #6f756f;
  --line: #e7e1d4;
  --radius: 8px;
  --shadow: 0 10px 30px rgba(31, 58, 48, .08);
  --serif: 'Cormorant Garamond', Georgia, serif;
  --sans: 'Inter', system-ui, sans-serif;

  font-family: var(--sans);
  color: var(--text);
  background: var(--cream);
  min-height: 100vh;
  padding-bottom: 60px;
}

.hotel-booking-widget h1, .hotel-booking-widget h2, .hotel-booking-widget h3 {
  font-family: var(--serif);
  color: var(--green);
  font-weight: 600;
}

.hotel-booking-widget .eyebrow {
  font-size: .72rem;
  letter-spacing: .22em;
  text-transform: uppercase;
  color: var(--muted);
  font-weight: 500;
  display: block;
  margin-bottom: 6px;
}

.hotel-booking-widget .page-banner {
  background: var(--green);
  color: var(--white);
  padding: 50px 20px;
  text-align: center;
}
.hotel-booking-widget .page-banner h1 { color: var(--white); font-size: 2.8rem; margin: 0; }
.hotel-booking-widget .page-banner p { color: rgba(255,255,255,.75); margin-top: 8px; font-size: 1rem; }
.hotel-booking-widget .page-banner .eyebrow { color: var(--sand); }

.hotel-booking-widget .booking-section { padding: 40px 15px; }
.hotel-booking-widget .booking-container { max-width: 1100px; margin: 0 auto; }

.hotel-booking-widget .form-layout {
  display: grid;
  grid-template-columns: 1.6fr 1fr;
  gap: 30px;
  align-items: start;
}
@media (max-width: 900px) {
  .hotel-booking-widget .form-layout { grid-template-columns: 1fr; }
}

.hotel-booking-widget .form-card {
  background: var(--white);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  padding: 34px;
}

.hotel-booking-widget .form-title { font-size: 2rem; margin: 0 0 4px; }
.hotel-booking-widget .form-sub { color: var(--muted); font-size: .9rem; margin-bottom: 24px; }

.hotel-booking-widget .user-status-banner {
  background: var(--green-soft);
  border: 1px solid #c2d6c6;
  color: var(--green);
  padding: 10px 16px;
  border-radius: var(--radius);
  margin-bottom: 20px;
  font-size: .88rem;
  display: flex;
  gap: 10px;
  align-items: center;
}
.hotel-booking-widget .user-status-banner.guest {
  background: #fdf6e9;
  border-color: #f1ddb6;
  color: #8a6420;
}

.hotel-booking-widget .form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}
@media (max-width: 600px) {
  .hotel-booking-widget .form-grid { grid-template-columns: 1fr; }
}

.hotel-booking-widget .field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.hotel-booking-widget .field.full { grid-column: 1 / -1; }
.hotel-booking-widget .field label {
  font-size: .72rem;
  letter-spacing: .12em;
  text-transform: uppercase;
  font-weight: 600;
  color: var(--green);
}
.hotel-booking-widget .field label .req { color: #b4483a; }
.hotel-booking-widget .field input, .hotel-booking-widget .field select {
  padding: 11px 14px;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: var(--cream);
  font-size: .92rem;
  outline: none;
  transition: .2s;
}
.hotel-booking-widget .field input:focus, .hotel-booking-widget .field select:focus {
  border-color: var(--sand-dark);
  background: var(--white);
  box-shadow: 0 0 0 3px rgba(230,199,156,.3);
}
.hotel-booking-widget .field input:disabled {
  opacity: 0.65;
  cursor: not-allowed;
}

.hotel-booking-widget .btn {
  display: inline-block;
  padding: 13px 24px;
  border-radius: var(--radius);
  font-size: .78rem;
  letter-spacing: .12em;
  text-transform: uppercase;
  font-weight: 600;
  cursor: pointer;
  border: 1px solid transparent;
  transition: .2s;
  text-align: center;
}
.hotel-booking-widget .btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
.hotel-booking-widget .btn-green {
  background: var(--green);
  color: var(--white);
}
.hotel-booking-widget .btn-green:hover:not(:disabled) {
  background: var(--green-dark);
  transform: translateY(-2px);
}
.hotel-booking-widget .btn-sand {
  background: var(--sand);
  color: var(--green);
}
.hotel-booking-widget .btn-sand:hover:not(:disabled) {
  background: var(--sand-dark);
}
.hotel-booking-widget .btn-outline {
  border-color: var(--green);
  color: var(--green);
  background: transparent;
}
.hotel-booking-widget .btn-outline:hover {
  background: var(--green);
  color: var(--white);
}
.hotel-booking-widget .btn-block { width: 100%; }

.hotel-booking-widget .summary {
  background: var(--green);
  color: var(--white);
  border-radius: var(--radius);
  padding: 28px;
  position: sticky;
  top: 30px;
}
.hotel-booking-widget .summary h3 { color: var(--white); margin: 0 0 16px; font-size: 1.5rem; }
.hotel-booking-widget .summary .eyebrow { color: var(--sand); }

.hotel-booking-widget .summary-row {
  display: flex;
  justify-content: space-between;
  padding: 10px 0;
  border-bottom: 1px solid rgba(255,255,255,.14);
  font-size: .88rem;
  color: rgba(255,255,255,.8);
}
.hotel-booking-widget .summary-row strong { color: var(--white); font-weight: 600; }

.hotel-booking-widget .summary-total {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin: 22px 0 16px;
}
.hotel-booking-widget .summary-total span { font-size: .72rem; letter-spacing: .14em; text-transform: uppercase; color: var(--sand); }
.hotel-booking-widget .summary-total strong { font-family: var(--serif); font-size: 2.2rem; color: var(--white); }

.hotel-booking-widget .summary .note {
  font-size: .75rem;
  color: rgba(255,255,255,.65);
  margin-top: 14px;
  line-height: 1.4;
}

.hotel-booking-widget .alert {
  padding: 12px 16px;
  border-radius: var(--radius);
  font-size: .86rem;
  margin-bottom: 18px;
  display: flex;
  gap: 10px;
  align-items: center;
  border-left: 4px solid;
}
.hotel-booking-widget .alert.error {
  background: #f8e4e0;
  border-color: #b4483a;
  color: #8a3a2f;
}

.hotel-booking-widget .badge.available {
  background: #dcebdf;
  color: #2c5a3f;
  padding: 3px 8px;
  border-radius: 12px;
  font-size: .72rem;
  text-transform: uppercase;
  font-weight: 600;
}

.hotel-booking-widget .custom-modal-backdrop {
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background: rgba(22,42,34,.65);
  z-index: 1050;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
}
.hotel-booking-widget .custom-modal {
  background: var(--white);
  border-radius: 12px;
  max-width: 480px;
  width: 100%;
  box-shadow: 0 25px 60px rgba(0,0,0,.25);
  overflow: hidden;
}
.hotel-booking-widget .dialog-body { padding: 32px; }
.hotel-booking-widget .dialog-total {
  font-family: var(--serif);
  font-size: 2.8rem;
  color: var(--green);
  font-weight: 700;
  margin: 8px 0 16px;
}
.hotel-booking-widget .summary-row.dark {
  color: var(--muted);
  border-color: var(--line);
}
.hotel-booking-widget .summary-row.dark strong { color: var(--text); }
.hotel-booking-widget .dialog-note {
  color: var(--muted);
  font-size: .82rem;
  margin-top: 16px;
}
.hotel-booking-widget .dialog-actions {
  display: flex;
  gap: 12px;
  justify-content: flex-end;
  margin-top: 24px;
}
.hotel-booking-widget .res-num-box {
  background: var(--cream);
  border: 2px dashed var(--sand-dark);
  padding: 16px;
  border-radius: 8px;
  text-align: center;
  margin-top: 14px;
}
.hotel-booking-widget .res-num-box small {
  text-transform: uppercase;
  letter-spacing: .12em;
  color: var(--muted);
  font-size: .7rem;
}
.hotel-booking-widget .res-num-box .res-num {
  font-family: var(--serif);
  font-size: 2rem;
  font-weight: 700;
  color: var(--green);
  margin-top: 4px;
}

sp_widget.script:
(function() {
  // 1. Detect Logged-In User or Guest
  data.isLoggedIn = gs.isLoggedIn();
  data.userId = gs.getUserID();
  data.userName = gs.getUserDisplayName();
  data.userEmail = gs.getUser().getEmail();

  // 2. Fetch Active Rooms for dropdown
  data.rooms = [];
  var roomGr = new GlideRecord('x_2206701_hotel_0_rooms');
  roomGr.addQuery('availability_status', '!=', 'maintenance');
  roomGr.orderBy('rate');
  roomGr.query();
  while (roomGr.next()) {
    data.rooms.push({
      sys_id: roomGr.getUniqueValue(),
      name: roomGr.getValue('room_name') || roomGr.getDisplayValue(),
      type: roomGr.getDisplayValue('room_type'),
      capacity: roomGr.getValue('capacity') || 2,
      rate: parseFloat(roomGr.getValue('rate')) || 0
    });
  }

  // 3. Handle Client Controller Actions
  if (input) {
    var pricingUtil = new x_2206701_hotel_0.PricingUtils();
    var resUtil = new x_2206701_hotel_0.ReservationUtils();

    // ACTION: Calculate Dynamic Price & Check Availability
    if (input.action === 'calculateEstimate') {
      var dateCheck = resUtil.validateDates(input.checkIn, input.checkOut);
      if (!dateCheck.ok) {
        data.dateError = dateCheck.message;
        data.isAvailable = false;
        data.estimatedTotal = 0;
        data.nights = 0;
        return;
      }

      data.dateError = '';
      data.nights = resUtil.calculateDays(input.checkIn, input.checkOut);

      // Check room availability via Cauban's PricingUtils
      var availCheck = pricingUtil.isRoomAvailable(input.selectedRoom, input.checkIn, input.checkOut);
      data.isAvailable = availCheck.available;
      data.availReason = availCheck.reason;

      // Calculate total with calendar discounts
      if (data.isAvailable) {
        data.estimatedTotal = pricingUtil.calculateRoomTotal(input.selectedRoom, data.nights, input.checkIn);
      } else {
        data.estimatedTotal = 0;
      }
    }

    // ACTION: Submit Reservation to Database via Sarsonas's ReservationUtils
    if (input.action === 'createBooking') {
      var bookingPayload = {
        room: input.selectedRoom,
        guest_name: input.guestName,
        guest_email: input.guestEmail,
        check_in_date: input.checkIn,
        check_out_date: input.checkOut,
        number_of_adults: parseInt(input.adults, 10) || 1,
        number_of_children: parseInt(input.children, 10) || 0,
        registered_user: data.isLoggedIn ? data.userId : ''
      };

      var createResult = resUtil.createReservation(bookingPayload);
      if (createResult.ok) {
        data.bookingSuccess = true;
        data.createdSysId = createResult.reservationId;

        // Fetch display reservation number (e.g. RES000012)
        var resGr = new GlideRecord('x_2206701_hotel_0_scheduled_reservations');
        if (resGr.get(createResult.reservationId)) {
          data.reservationDisplayNumber = resGr.getValue('number') || createResult.reservationId;
        } else {
          data.reservationDisplayNumber = createResult.reservationId;
        }
      } else {
        data.bookingSuccess = false;
        data.bookingError = createResult.message;
      }
    }
  }
})();
